// OrchdServer is the server API for Orchd service.
// All implementations must embed UnimplementedOrchdServer
// for forward compatibility.
//
// Orchd is the local control-plane the CLI, hooks, and MCP servers dial over a
// Unix-domain socket.
type OrchdServer interface {
	// Ping is a liveness/health check.
	Ping(context.Context, *PingRequest) (*PingResponse, error)
	// Ingest chunks, embeds, and stores text in the vector store.
	Ingest(context.Context, *IngestRequest) (*IngestResponse, error)
	// Search embeds the query and returns the top matching chunks.
	Search(context.Context, *SearchRequest) (*SearchResponse, error)
	// ListSources enumerates the distinct sources held in the vector store, with
	// per-source chunk counts. This is the store's inventory, as opposed to the
	// cadence-refresh registry that `orch source list` reports.
	ListSources(context.Context, *ListSourcesRequest) (*ListSourcesResponse, error)
	// DeleteSource removes every chunk belonging to one source_uri.
	DeleteSource(context.Context, *DeleteSourceRequest) (*DeleteSourceResponse, error)
	// Dispatch enqueues a durable agent-task workflow and returns its instance ID.
	Dispatch(context.Context, *DispatchRequest) (*DispatchResponse, error)
	// ListTasks returns dispatched tasks, newest first, optionally by status.
	ListTasks(context.Context, *ListTasksRequest) (*ListTasksResponse, error)
	// GetTask returns one dispatched task by ID.
	GetTask(context.Context, *GetTaskRequest) (*GetTaskResponse, error)
	// Status reports orchd's own health plus one entry per supervised subsystem.
	Status(context.Context, *StatusRequest) (*StatusResponse, error)
	// Restart restarts one supervised subsystem in place — no process bounce.
	// An empty name restarts every subsystem.
	Restart(context.Context, *RestartRequest) (*RestartResponse, error)
	// SummarizeSession queues a finished session for a model-written summary,
	// which replaces the excerpt in its session record. It returns at once.
	SummarizeSession(context.Context, *SummarizeSessionRequest) (*SummarizeSessionResponse, error)
	// RecommendModel answers which model a task of one kind should run on, with
	// the evidence behind the answer.
	RecommendModel(context.Context, *RecommendModelRequest) (*RecommendModelResponse, error)
	// RateTask records the user's verdict on a finished task, evidence for routing.
	RateTask(context.Context, *RateTaskRequest) (*RateTaskResponse, error)
	// RetryTask runs a task again; the runner resumes its session when one
	// exists. Refused while the task's run is still active.
	RetryTask(context.Context, *RetryTaskRequest) (*RetryTaskResponse, error)
	// CancelTask stops a pending or in-progress task.
	CancelTask(context.Context, *CancelTaskRequest) (*CancelTaskResponse, error)
	// WatchTasks streams task changes: a snapshot of the newest tasks, then
	// each task whose ledger row or live run changes, and a periodic tick with
	// the unsettled tasks so their liveness (last activity) stays current.
	WatchTasks(*WatchTasksRequest, grpc.ServerStreamingServer[TaskEvent]) error
	// MigrateHybrid copies the RAG collection into a new hybrid one (dense plus
	// BM25 keyword vectors), re-chunking and re-embedding its text, and switches
	// to it. Without apply it only plans. The old collection is kept.
	MigrateHybrid(context.Context, *MigrateHybridRequest) (*MigrateHybridResponse, error)
	// DropBackup deletes the backup collection a migration kept; plans unless apply.
	DropBackup(context.Context, *DropBackupRequest) (*DropBackupResponse, error)
	// ReindexKeywords recomputes, in place, the BM25 keyword vectors an older
	// tokenizer made, from each chunk's stored text; counts unless apply.
	// Resumable: chunks already re-indexed are skipped.
	ReindexKeywords(context.Context, *ReindexKeywordsRequest) (*ReindexKeywordsResponse, error)
	// BackfillSessions stores sessions again from their transcripts on disk.
	BackfillSessions(context.Context, *BackfillSessionsRequest) (*BackfillSessionsResponse, error)
	// ListPRs serves the PR babysitter's cache: the user's open PRs and PRs
	// awaiting their review, each with why it needs attention. Never calls gh.
	ListPRs(context.Context, *ListPRsRequest) (*ListPRsResponse, error)
	// GetGitHubIdentity returns the user's GitHub login, orgs and teams as gh
	// sees them; cached for 10 minutes unless refresh is set.
	GetGitHubIdentity(context.Context, *GetGitHubIdentityRequest) (*GitHubIdentity, error)
	// ListGitHubScopes returns what the GitHub watcher may monitor: the user's
	// own account (on by default) and each org they belong to (off by default).
	ListGitHubScopes(context.Context, *ListGitHubScopesRequest) (*ListGitHubScopesResponse, error)
	// SetGitHubScope turns a discovered scope on or off and sets what it covers.
	SetGitHubScope(context.Context, *SetGitHubScopeRequest) (*SetGitHubScopeResponse, error)
	// ListGitHubRepos lists the repos the user can see under an owner.
	ListGitHubRepos(context.Context, *ListGitHubReposRequest) (*ListGitHubReposResponse, error)
	// ListGitHubItems serves the watcher's cache: open PRs and issues in the
	// enabled scopes, each with why it is watched. Never calls gh.
	ListGitHubItems(context.Context, *ListGitHubItemsRequest) (*ListGitHubItemsResponse, error)
	// RequestGitHubSweep asks the watcher to search GitHub soon, spaced like any
	// other requested sweep. The caller sees the result as ListGitHubItems'
	// updated_at advancing; this RPC does not wait for it.
	RequestGitHubSweep(context.Context, *RequestGitHubSweepRequest) (*RequestGitHubSweepResponse, error)
	// ListPRReviews lists the PRs the user asked orchd to review once ready,
	// each with where its review stands and the last verdict. Never calls gh.
	ListPRReviews(context.Context, *ListPRReviewsRequest) (*ListPRReviewsResponse, error)
	// WatchPRReview starts watching a PR for review, or changes what orchd may
	// post for it: nothing (verdict), an approval on an approve verdict
	// (approve), the drafted comment on any other verdict (feedback), both
	// (auto), or the drafted comment once, now (comment). The PR is checked
	// within seconds.
	WatchPRReview(context.Context, *WatchPRReviewRequest) (*PRReview, error)
	// SetPRReviewUpdateInPlace changes whether a later comment edits orch's
	// earlier one on a watched PR, and nothing else: it never posts or reviews.
	SetPRReviewUpdateInPlace(context.Context, *SetPRReviewUpdateInPlaceRequest) (*PRReview, error)
	// StopPRReview stops watching a PR; forget also deletes its verdict.
	StopPRReview(context.Context, *StopPRReviewRequest) (*StopPRReviewResponse, error)
	// GetPRDetail reads one PR's metadata from GitHub (one gh call), cached for
	// a minute unless refresh is set.
	GetPRDetail(context.Context, *GetPRDetailRequest) (*PRDetail, error)
	// TailLogs returns orchd's recent log lines, kept in memory, after a
	// sequence number, so a caller can poll for new lines.
	TailLogs(context.Context, *TailLogsRequest) (*TailLogsResponse, error)
	// GetSystemMetrics reports resource use of orchd and the processes it runs,
	// the size of its data, and task counts.
	GetSystemMetrics(context.Context, *GetSystemMetricsRequest) (*SystemMetrics, error)
	// ListDocs lists the GitHub owners whose docs orchd keeps in sync, their
	// repos, and every doc of theirs the store holds, with its GitHub location.
	ListDocs(context.Context, *ListDocsRequest) (*ListDocsResponse, error)
	// GetDocument rebuilds one indexed source from its stored chunks.
	GetDocument(context.Context, *GetDocumentRequest) (*Document, error)
	// SyncDocs starts a docs sync now: one owner or every owner, and with force
	// a full re-ingest. Only one sync runs at a time; a request while one runs
	// is refused (Aborted), never queued.
	SyncDocs(context.Context, *SyncDocsRequest) (*DocsSyncState, error)
	// GetDocsSync reports the running docs sync, or the last one.
	GetDocsSync(context.Context, *GetDocsSyncRequest) (*DocsSyncState, error)
	// ListDocsOwners returns the owners the docs sync tracks and what each covers.
	ListDocsOwners(context.Context, *ListDocsOwnersRequest) (*ListDocsOwnersResponse, error)
	// ListDocsOwnerRepos asks GitHub for an owner's repos, to choose among them;
	// the owner need not be registered.
	ListDocsOwnerRepos(context.Context, *ListDocsOwnerReposRequest) (*ListDocsOwnerReposResponse, error)
	// SaveDocsOwner registers an owner if needed and sets whether it syncs and
	// which repos it covers. Refused while a docs sync runs.
	SaveDocsOwner(context.Context, *SaveDocsOwnerRequest) (*DocOwner, error)
	// RemoveDocsOwner forgets an owner, and with purge and confirm deletes what
	// it indexed. Refused while a docs sync runs.
	RemoveDocsOwner(context.Context, *RemoveDocsOwnerRequest) (*PurgeDocsResponse, error)
	// PurgeDocs deletes the indexed docs of repos an owner no longer covers.
	// Permanent: needs confirm. Refused while a docs sync runs.
	PurgeDocs(context.Context, *PurgeDocsRequest) (*PurgeDocsResponse, error)
	// GetConfig returns every setting, described for editing. Settings live in
	// orch.db; this and SetConfig are the only way to change them.
	GetConfig(context.Context, *GetConfigRequest) (*ConfigState, error)
	// SetConfig validates and writes settings in one write: all of them or none.
	// A value equal to the default resets the setting to follow the default.
	SetConfig(context.Context, *SetConfigRequest) (*ConfigState, error)
	// RemoveLegacyConfig deletes the config.yaml orch no longer reads, once its
	// settings were imported.
	RemoveLegacyConfig(context.Context, *RemoveLegacyConfigRequest) (*ConfigState, error)
	// SetSpacesDraft saves a spaces policy as a new draft revision. It changes
	// nothing that is enforced; the reply lists the draft's problems.
	SetSpacesDraft(context.Context, *SetSpacesDraftRequest) (*SpacesDraft, error)
	// DiffSpaces compares the enforced spaces revision with the newest draft.
	// Operator-only, like ApplySpaces: the policy names every job's orgs and
	// roots.
	DiffSpaces(context.Context, *DiffSpacesRequest) (*SpacesDiff, error)
	// ApplySpaces enforces the newest draft. Operator-only: refused to callers
	// descended from a harness or from orchd, and to any revision but the
	// newest, so the operator applies exactly what they reviewed. A draft an
	// agent session saved also needs accept_agent_draft.
	ApplySpaces(context.Context, *ApplySpacesRequest) (*ApplySpacesResponse, error)
	// ExplainPlacement says which space content from a target (a path, URL,
	// owner/repo or chat tenant) goes to and why. Agents get an answer only
	// when every space it names is public; the operator sees all.
	ExplainPlacement(context.Context, *ExplainPlacementRequest) (*PlacementExplanation, error)
	// ListRegisteredSources lists the sources registered for refresh on a
	// cadence (web URLs, local repos, local owner directories).
	ListRegisteredSources(context.Context, *ListRegisteredSourcesRequest) (*ListRegisteredSourcesResponse, error)
	// SaveSource adds or updates a registered source.
	SaveSource(context.Context, *SaveSourceRequest) (*RegisteredSource, error)
	// RemoveSource unregisters a source, optionally deleting what it indexed.
	RemoveSource(context.Context, *RemoveSourceRequest) (*RemoveSourceResponse, error)
	// RefreshSource refreshes one registered source, or all, now.
	RefreshSource(context.Context, *RefreshSourceRequest) (*RefreshSourceResponse, error)
	// GetSafetyNet reports how cc-safety-net is installed in Claude Code
	// against the version this orch pins, the guard rules, and the last
	// install action. Read from plugin and rule files; runs no command.
	GetSafetyNet(context.Context, *GetSafetyNetRequest) (*SafetyNetState, error)
	// InstallSafetyNet installs, upgrades or repairs cc-safety-net and the
	// orch-guards rules, and returns the resulting state. One action runs at a
	// time; a request while one runs is refused (Aborted), never queued.
	InstallSafetyNet(context.Context, *InstallSafetyNetRequest) (*SafetyNetState, error)
	// ListSettings lists the settings orch manages in other tools' files
	// (Claude Code hooks, permission rules and plugins, cc-safety-net rules),
	// each with its desired state and origin, and each provider's kinds with
	// the fields an add form needs. It reads the files first, so the list
	// reflects changes made outside orch.
	ListSettings(context.Context, *ListSettingsRequest) (*ListSettingsResponse, error)
	// SetSettingEnabled turns one item on or off: it is written into, or
	// taken out of, its file at once, and the choice is kept in orch.db.
	SetSettingEnabled(context.Context, *SetSettingEnabledRequest) (*SettingItem, error)
	// AddSetting validates a new item (a hook or a permission rule), writes it
	// to its file and records it as added by you.
	AddSetting(context.Context, *AddSettingRequest) (*SettingItem, error)
	// RemoveSetting deletes an item you added or orch found from its file and
	// forgets it. Items orch install writes can only be turned off.
	RemoveSetting(context.Context, *RemoveSettingRequest) (*RemoveSettingResponse, error)
	// GetTaskActivity reads what a task's session has done so far from its
	// transcript: commands, edits and reads, with risky commands marked.
	GetTaskActivity(context.Context, *GetTaskActivityRequest) (*TaskActivity, error)
	// GetPRLanding shows the commit a task proposed for its PR, checked against
	// the PR's current head, and what the user decided about it.
	GetPRLanding(context.Context, *PRLandingRequest) (*PRLanding, error)
	// ListPRLandings lists the decided landings, without calling GitHub, so the
	// app can tell which proposals still wait on the user.
	ListPRLandings(context.Context, *ListPRLandingsRequest) (*ListPRLandingsResponse, error)
	// LandPR pushes the proposed commit to the PR's branch, fast-forward only.
	LandPR(context.Context, *LandPRRequest) (*PRLanding, error)
	// UndoPRLanding pushes a new commit restoring the tree the PR had before
	// the landing. It never rewrites history.
	UndoPRLanding(context.Context, *PRLandingRequest) (*PRLanding, error)
	// DiscardPRLanding sets a proposal aside, or with restore brings it back.
	DiscardPRLanding(context.Context, *DiscardPRLandingRequest) (*PRLanding, error)
	mustEmbedUnimplementedOrchdServer()
}

